const ing = (ingredientId: string, name: string, quantity: string, unit: any, optional = false) => ({ ingredientId, name, quantity, unit, optional });
const nutrition=(protein:string,ingredients:ReturnType<typeof ing>[])=>{const key=protein.toLowerCase();const proteinGramsPerServing=key.includes('chicken')?43:key.includes('salmon')?38:key.includes('tuna')?39:key.includes('fish')?35:key.includes('shrimp')?34:key.includes('beef')?37:key.includes('steak')?39:key.includes('egg')?25:key.includes('tofu')?22:key.includes('bean')||key.includes('chickpea')||key.includes('lentil')?19:24;const starch=ingredients.some(item=>/(rice|pasta|potato|tortilla|bread|noodle|gnocchi|flour|oat)/i.test(item.name));return {caloriesPerServing:(starch?620:490)+(key.includes('cheese')?80:0),proteinGramsPerServing}};
const scaled=(quantity:string,factor:number)=>String(Number((Number(quantity)*factor).toFixed(4)));
const make = (id: string, title: string, description: string, cuisine: string, protein: string, servings: number, prepMinutes: number, cookMinutes: number, estimatedCost: string, cleanup: 1|2|3|4|5, leftoverQuality: 1|2|3|4|5, ingredients: ReturnType<typeof ing>[], steps: string[], tags: string[], difficulty: Recipe['difficulty'] = 'Easy', safetyNote?: string): Recipe => {const factor=2/servings;const twoServingIngredients=ingredients.map(item=>({...item,quantity:scaled(item.quantity,factor)}));return { id, version: 1, title, description, cuisine, protein, servings:2, prepMinutes, cookMinutes, difficulty, estimatedCost:(Number(estimatedCost)*factor).toFixed(2),...nutrition(protein,twoServingIngredients),cleanup, leftoverQuality, leftoverDays:1, ingredients:twoServingIngredients, steps, tags, reheating:'Refrigerate the second serving promptly and reheat it until steaming for lunch tomorrow.', equipment: cleanup <= 2 ? ['Large skillet', 'Cutting board'] : ['Sheet pan', 'Saucepan', 'Cutting board'], ...(safetyNote ? { safetyNote } : {}) }};
